{#-
  ══════════════════════════════════════════════════════════════════════
  Customer Product Specification — spec sheet
  SINGLE SOURCE for BOTH print formats. push_cps_board_plan.py generates:

    "Customer Product Spec"               CALCULATED = false
    "Customer Product Spec (Calculated)"  CALCULATED = true

  by rewriting the CALCULATED line below. Never edit the two generated
  formats in the Frappe UI — edit this file and re-push, or the layouts
  drift apart.

  CALCULATED = false → Board Plan reads the stored board_* fields, falling
                       back to the computed value where a field is empty.
  CALCULATED = true  → Board Plan is recomputed from the carton dimensions
                       and the stored board_* fields are ignored entirely.
                       This is the variant for the back-catalogue of specs
                       submitted before the Board Plan fields existed.

  wkhtmltopdf: no named @page rules (silently ignored), and the last page
  container must suppress page-break-after or a blank sheet is emitted.
  ══════════════════════════════════════════════════════════════════════
-#}
{%- set CALCULATED = false -%}

{#- ── Inputs ──────────────────────────────────────────────────────── -#}
{%- set pt        = doc.product_type_carton or "" -%}
{%- set ply       = doc.ply or "" -%}
{%- set L         = doc.ctn_length_mm or 0 -%}
{%- set W         = doc.ctn_width_mm or 0 -%}
{%- set H         = doc.ctn_height_mm or 0 -%}
{%- set joint     = doc.joint_type or "Stitched" -%}
{%- set is_stitch = (joint == "Stitched") -%}
{#- VCL standard: 30mm tab for every joint type (stitch flap reduced from 40mm 2026-07-23). -#}
{%- set tab       = 30 -%}
{%- set TRIM      = 10 -%}

{%- set is_carton = (doc.product_type == "Carton") -%}
{%- set is_tray   = (pt == "Tray") -%}
{%- set one_flap  = (pt == "1 Flap RSC") -%}
{%- set drawable  = is_carton and ply != "SFK" and pt not in ["", "Die Cut"] and L > 0 and W > 0
                    and (is_tray or (H > 0)) -%}

{#- ── Flap ─────────────────────────────────────────────────────────── -#}
{%- set flap_calc = 0 if ply == "SFK" else (((W + 5) / 2) | round(0, 'ceil') | int) -%}
{%- if CALCULATED -%}
  {%- set flap = flap_calc -%}
{%- else -%}
  {%- set flap = doc.ctn_flap_mm or flap_calc -%}
{%- endif -%}

{#- ── Blank sizes ──────────────────────────────────────────────────── -#}
{%- if is_tray -%}
  {%- set bw = W + 2 * H -%}
  {%- set bl = L + 2 * H -%}
{%- elif one_flap -%}
  {%- set bw = H + flap -%}
  {%- set bl = (2 * L) + (2 * W) + tab -%}
{%- else -%}
  {%- set bw = flap + H + flap -%}
  {%- set bl = (2 * L) + (2 * W) + tab -%}
{%- endif -%}

{%- set pw_calc = bw + (2 * TRIM) -%}
{%- set pl_calc = bl + (2 * TRIM) -%}

{#- ── GSM build-up ─────────────────────────────────────────────────── -#}
{%- set gsm_12 = (doc.get('1_ply_top_layer_gsm') or 0) + (doc.get('2_ply_fluting_gsm') or 0) -%}
{%- set gsm_3  = (doc.get('3_ply_bottom_gsm') or 0) if ply in ["3", "5"] else 0 -%}
{%- set gsm_45 = ((doc.get('4_ply_fluting_gsm') or 0) + (doc.get('5_ply_fluting_gsm') or 0)) if ply == "5" else 0 -%}
{%- set total_gsm = gsm_12 + gsm_3 + gsm_45 -%}

{#- ── Resolve the figures actually printed ─────────────────────────── -#}
{%- set stale = false -%}
{%- if CALCULATED -%}
  {%- set pw = pw_calc -%}
  {%- set pl = pl_calc -%}
  {%- set aw = bw -%}
  {%- set al = bl -%}
  {%- set weight = ((pw_calc * pl_calc) / 1000000.0) * total_gsm -%}
{%- else -%}
  {#- The geometry fully determines the blank, so stored values that disagree with
      it are stale, not a legitimate override. Printing them produced a Planned
      smaller than its own Blank on CTN-SPEC-00022. Fall back to the computed
      figures and say so, rather than print an impossible table. -#}
  {%- set s_aw = doc.board_width_actual_mm or 0 -%}
  {%- set s_al = doc.board_length_actual_mm or 0 -%}
  {%- set s_pw = doc.board_width_planned_mm or 0 -%}
  {%- set s_pl = doc.board_length_planned_mm or 0 -%}
  {%- if (s_aw and s_aw != bw) or (s_al and s_al != bl)
       or (s_pw and s_pw != pw_calc) or (s_pl and s_pl != pl_calc) -%}
    {%- set stale = true -%}
    {%- set pw = pw_calc -%}
    {%- set pl = pl_calc -%}
    {%- set aw = bw -%}
    {%- set al = bl -%}
    {%- set weight = ((pw_calc * pl_calc) / 1000000.0) * total_gsm -%}
  {%- else -%}
    {%- set pw = s_pw or pw_calc -%}
    {%- set pl = s_pl or pl_calc -%}
    {%- set aw = s_aw or bw -%}
    {%- set al = s_al or bl -%}
    {%- set weight = doc.approximate_weight_grams or (((pw_calc * pl_calc) / 1000000.0) * total_gsm) -%}
  {%- endif -%}
{%- endif -%}

{#- ══ Flat blank — RSC ═════════════════════════════════════════════ -#}
{%- macro flat_rsc(L, W, H, flap, tab, one_flap, is_stitch) -%}
  {%- set totalW = tab + (2 * L) + (2 * W) -%}
  {%- set totalH = (H + flap) if one_flap else (flap + H + flap) -%}
  {#- Widths are tuned to A4 at 12mm margins (~700 CSS px of content box). -#}
  {%- set scale  = [0.40, 510.0 / totalW, 175.0 / totalH] | min -%}
  {%- set ox = 34 -%}{%- set oy = 30 -%}
  {%- set body_y = 0 if one_flap else flap -%}
  {%- set svgW = (totalW * scale) + 76 -%}
  {%- set svgH = (totalH * scale) + 74 -%}{#- room for the dimension row + blank caption -#}
  {%- set tab_fill = '#F7D8D8' if is_stitch else '#D2EBD3' -%}
  {%- set tab_label = 'Stitch Flap' if is_stitch else 'Glue Tab' -%}
<svg width="{{ svgW|round(1) }}" height="{{ svgH|round(1) }}" viewBox="0 0 {{ svgW|round(1) }} {{ svgH|round(1) }}"
     style="background:#FAFAFA;border:1px solid #ddd;border-radius:4px;">
  {#- Panel width L is a Front/Back face; panel width W is a Side face. -#}
  {%- set body = [
        (0, tab, tab_fill, tab_label),
        (tab, L, '#E2E4F4', 'Front (' ~ L ~ ')'),
        (tab + L, W, '#DBDEF1', 'Side (' ~ W ~ ')'),
        (tab + L + W, L, '#E2E4F4', 'Back (' ~ L ~ ')'),
        (tab + L + W + L, W, '#DBDEF1', 'Side (' ~ W ~ ')')
      ] -%}
  {%- for x, w, fill, label in body %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ (oy + body_y * scale)|round(2) }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (H * scale)|round(2) }}"
        fill="{{ fill }}" stroke="#333333" stroke-width="1.5"/>
  {%- if (w * scale) > 34 %}
  <text x="{{ (ox + (x + w / 2.0) * scale)|round(2) }}" y="{{ (oy + (body_y + H / 2.0) * scale)|round(2) }}"
        text-anchor="middle" dominant-baseline="middle" font-size="9" fill="#333" font-weight="500">{{ label }}</text>
  {%- endif %}
  {%- endfor %}
  {%- set flaps = [(tab, L), (tab + L, W), (tab + L + W, L), (tab + L + W + L, W)] -%}
  {%- for x, w in flaps %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ (oy + (body_y + H) * scale)|round(2) }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (flap * scale)|round(2) }}"
        fill="#DDE1F2" stroke="#333333" stroke-width="1.5"/>
  {%- if not one_flap %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ oy }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (flap * scale)|round(2) }}"
        fill="#DDE1F2" stroke="#333333" stroke-width="1.5"/>
  {%- endif %}
  <line x1="{{ (ox + x * scale)|round(2) }}" y1="{{ oy }}"
        x2="{{ (ox + x * scale)|round(2) }}" y2="{{ (oy + totalH * scale)|round(2) }}"
        stroke="#FF6B35" stroke-width="1.4" stroke-dasharray="6,4"/>
  {%- endfor %}
  <line x1="{{ (ox + tab * scale)|round(2) }}" y1="{{ (oy + (body_y + H) * scale)|round(2) }}"
        x2="{{ (ox + totalW * scale)|round(2) }}" y2="{{ (oy + (body_y + H) * scale)|round(2) }}"
        stroke="#FF6B35" stroke-width="1" stroke-dasharray="4,3"/>
  {%- if not one_flap %}
  <line x1="{{ (ox + tab * scale)|round(2) }}" y1="{{ (oy + flap * scale)|round(2) }}"
        x2="{{ (ox + totalW * scale)|round(2) }}" y2="{{ (oy + flap * scale)|round(2) }}"
        stroke="#FF6B35" stroke-width="1" stroke-dasharray="4,3"/>
  {%- else %}
  <text x="{{ (ox + (totalW / 2.0) * scale)|round(2) }}" y="{{ oy - 10 }}"
        text-anchor="middle" font-size="8" fill="#999" font-style="italic">Open end (no flap)</text>
  {%- endif %}
  <text x="{{ (ox + (tab + L / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 13)|round(2) }}"
        text-anchor="middle" font-size="9" fill="#666">{{ L }}mm</text>
  <text x="{{ (ox + (tab + L + W / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 13)|round(2) }}"
        text-anchor="middle" font-size="9" fill="#666">{{ W }}mm</text>
  <text x="{{ (ox + totalW * scale + 5)|round(2) }}" y="{{ (oy + (body_y + H / 2.0) * scale)|round(2) }}"
        text-anchor="start" dominant-baseline="middle" font-size="9" fill="#666">{{ H }}mm</text>
  <text x="{{ (ox + totalW * scale + 5)|round(2) }}" y="{{ (oy + (body_y + H + flap / 2.0) * scale)|round(2) }}"
        text-anchor="start" dominant-baseline="middle" font-size="9" fill="#666">{{ flap }}mm</text>
  <text x="{{ (ox + (totalW / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 32)|round(2) }}"
        text-anchor="middle" font-size="10" fill="#2B3990" font-weight="600">Blank: {{ totalH }} (W) x {{ totalW }} (L) mm</text>
</svg>
{%- endmacro -%}

{#- ══ Flat blank — Tray ════════════════════════════════════════════ -#}
{%- macro flat_tray(L, W, H) -%}
  {%- set totalW = H + W + H -%}
  {%- set totalH = H + L + H -%}
  {%- set scale  = [0.52, 380.0 / totalW, 250.0 / totalH] | min -%}
  {%- set ox = 30 -%}{%- set oy = 30 -%}
  {%- set svgW = (totalW * scale) + 60 -%}
  {%- set svgH = (totalH * scale) + 74 -%}
<svg width="{{ svgW|round(1) }}" height="{{ svgH|round(1) }}" viewBox="0 0 {{ svgW|round(1) }} {{ svgH|round(1) }}"
     style="background:#FAFAFA;border:1px solid #ddd;border-radius:4px;">
  {%- set panels = [
        (H, H, W, L, '#E7E0F4', 'Base (' ~ L ~ ' x ' ~ W ~ ')'),
        (H, 0, W, H, '#D7EDD8', 'Front'),
        (H, H + L, W, H, '#D7EDD8', 'Back'),
        (0, H, H, L, '#E5F3E5', 'Side'),
        (H + W, H, H, L, '#E5F3E5', 'Side')
      ] -%}
  {%- for x, y, w, h, fill, label in panels %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ (oy + y * scale)|round(2) }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (h * scale)|round(2) }}"
        fill="{{ fill }}" stroke="#333333" stroke-width="1.5"/>
  {%- if (w * scale) > 44 and (h * scale) > 16 %}
  <text x="{{ (ox + (x + w / 2.0) * scale)|round(2) }}" y="{{ (oy + (y + h / 2.0) * scale)|round(2) }}"
        text-anchor="middle" dominant-baseline="middle" font-size="9" fill="#333" font-weight="500">{{ label }}</text>
  {%- endif %}
  {%- endfor %}
  {%- for fx in [H, H + W] %}
  <line x1="{{ (ox + fx * scale)|round(2) }}" y1="{{ oy }}" x2="{{ (ox + fx * scale)|round(2) }}"
        y2="{{ (oy + totalH * scale)|round(2) }}" stroke="#FF6B35" stroke-width="1.4" stroke-dasharray="6,4"/>
  {%- endfor %}
  {%- for fy in [H, H + L] %}
  <line x1="{{ ox }}" y1="{{ (oy + fy * scale)|round(2) }}" x2="{{ (ox + totalW * scale)|round(2) }}"
        y2="{{ (oy + fy * scale)|round(2) }}" stroke="#FF6B35" stroke-width="1.4" stroke-dasharray="6,4"/>
  {%- endfor %}
  <text x="{{ (ox + (totalW / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 30)|round(2) }}"
        text-anchor="middle" font-size="10" fill="#2B3990" font-weight="600">Blank: {{ totalW }} x {{ totalH }} mm</text>
</svg>
{%- endmacro -%}

{#- ══ Assembled box ════════════════════════════════════════════════ -#}
{%- macro assembled(L, W, H, open_top, caption) -%}
  {%- set DX = 0.50 -%}{%- set DY = 0.30 -%}
  {%- set scale = [0.34, 150.0 / (L + W * DX), 130.0 / (H + W * DY)] | min -%}
  {%- set l = L * scale -%}{%- set h = H * scale -%}
  {%- set dx = W * scale * DX -%}{%- set dy = W * scale * DY -%}
  {#- Left margin clears the "H 000mm" callout (anchored end), right margin the "W 000mm" -#}
  {%- set ox = 52 -%}{%- set oy = 28 + dy -%}
  {%- set svgW = l + dx + 110 -%}
  {%- set svgH = h + dy + 62 -%}
<svg width="{{ svgW|round(1) }}" height="{{ svgH|round(1) }}" viewBox="0 0 {{ svgW|round(1) }} {{ svgH|round(1) }}"
     style="background:#FAFAFA;border:1px solid #ddd;border-radius:4px;">
  {%- if open_top %}
  <polygon points="{{ (ox + 3)|round(2) }},{{ (oy + 2)|round(2) }}
                   {{ (ox + l - 3)|round(2) }},{{ (oy + 2)|round(2) }}
                   {{ (ox + l - 3 + dx)|round(2) }},{{ (oy + 2 - dy)|round(2) }}
                   {{ (ox + 3 + dx)|round(2) }},{{ (oy + 2 - dy)|round(2) }}"
           fill="#C1C5E1" stroke="#333333" stroke-width="0.8"/>
  {%- else %}
  <polygon points="{{ ox }},{{ oy|round(2) }} {{ (ox + l)|round(2) }},{{ oy|round(2) }}
                   {{ (ox + l + dx)|round(2) }},{{ (oy - dy)|round(2) }} {{ (ox + dx)|round(2) }},{{ (oy - dy)|round(2) }}"
           fill="#BCC2E5" stroke="#333333" stroke-width="1.6"/>
  {%- endif %}
  <polygon points="{{ (ox + l)|round(2) }},{{ oy|round(2) }}
                   {{ (ox + l + dx)|round(2) }},{{ (oy - dy)|round(2) }}
                   {{ (ox + l + dx)|round(2) }},{{ (oy - dy + h)|round(2) }}
                   {{ (ox + l)|round(2) }},{{ (oy + h)|round(2) }}"
           fill="#C9CEEA" stroke="#333333" stroke-width="1.6"/>
  <rect x="{{ ox }}" y="{{ oy|round(2) }}" width="{{ l|round(2) }}" height="{{ h|round(2) }}"
        fill="#D1D5ED" stroke="#333333" stroke-width="1.8"/>
  {%- if open_top %}
  <line x1="{{ ox }}" y1="{{ oy|round(2) }}" x2="{{ (ox + dx)|round(2) }}" y2="{{ (oy - dy)|round(2) }}"
        stroke="#333333" stroke-width="1.6"/>
  <line x1="{{ (ox + dx)|round(2) }}" y1="{{ (oy - dy)|round(2) }}"
        x2="{{ (ox + l + dx)|round(2) }}" y2="{{ (oy - dy)|round(2) }}" stroke="#333333" stroke-width="1.6"/>
  <text x="{{ (ox + l / 2.0 + dx / 2.0)|round(2) }}" y="{{ (oy - dy - 7)|round(2) }}"
        text-anchor="middle" font-size="8" fill="#999" font-style="italic">Open top</text>
  {%- endif %}
  <text x="{{ (ox + l / 2.0)|round(2) }}" y="{{ (oy + h / 2.0)|round(2) }}"
        text-anchor="middle" dominant-baseline="middle" font-size="9" fill="#333" font-weight="500">{{ L }} x {{ H }}</text>
  <text x="{{ (ox + l / 2.0)|round(2) }}" y="{{ (oy + h + 15)|round(2) }}"
        text-anchor="middle" font-size="9" fill="#666">L {{ L }}mm</text>
  <text x="{{ (ox - 7)|round(2) }}" y="{{ (oy + h / 2.0)|round(2) }}"
        text-anchor="end" dominant-baseline="middle" font-size="9" fill="#666">H {{ H }}mm</text>
  {#- W is the receding depth. Dimension it on the top-LEFT receding edge: that
      edge is on the silhouette, so the callout sits outside the solid. Placed at
      the right it landed beside the right face's vertical edge and read as the
      height. Angle is constant — atan(DY/DX) = 31 degrees — so it can be hardcoded. -#}
  {%- set nlen = ((dx * dx) + (dy * dy)) ** 0.5 -%}
  {%- set nx = -dy / nlen -%}{%- set ny = -dx / nlen -%}
  {%- set k = 11 -%}
  <line x1="{{ (ox + k * nx)|round(2) }}" y1="{{ (oy + k * ny)|round(2) }}"
        x2="{{ (ox + dx + k * nx)|round(2) }}" y2="{{ (oy - dy + k * ny)|round(2) }}"
        stroke="#999" stroke-width="0.6"/>
  <line x1="{{ ox }}" y1="{{ oy|round(2) }}" x2="{{ (ox + k * nx)|round(2) }}"
        y2="{{ (oy + k * ny)|round(2) }}" stroke="#999" stroke-width="0.5"/>
  <line x1="{{ (ox + dx)|round(2) }}" y1="{{ (oy - dy)|round(2) }}"
        x2="{{ (ox + dx + k * nx)|round(2) }}" y2="{{ (oy - dy + k * ny)|round(2) }}"
        stroke="#999" stroke-width="0.5"/>
  {%- set wlx = ox + (dx / 2.0) + (k + 8) * nx -%}
  {%- set wly = oy - (dy / 2.0) + (k + 8) * ny -%}
  <text x="{{ wlx|round(2) }}" y="{{ wly|round(2) }}" text-anchor="middle" dominant-baseline="middle"
        font-size="9" fill="#666"
        transform="rotate(-31, {{ wlx|round(2) }}, {{ wly|round(2) }})">W {{ W }}mm</text>
  <text x="{{ (ox + (l + dx) / 2.0)|round(2) }}" y="{{ (svgH - 9)|round(2) }}"
        text-anchor="middle" font-size="10" fill="#2B3990" font-weight="600">{{ caption }}</text>
</svg>
{%- endmacro -%}

<style>
  @page { size: A4; margin: 10mm 12mm; }
  .cps-wrap { font-family: 'Inter', Calibri, Arial, sans-serif; color: #1a1a1a; font-size: 10.5px; line-height: 1.3; }
  /* wkhtmltopdf emits a trailing blank sheet unless the container suppresses
     page-break-after AND its last child has no bottom margin. :last-child alone
     is not enough — printview may wrap the format in further elements. */
  .cps-wrap { page-break-after: avoid; margin-bottom: 0; padding-bottom: 0; }
  .cps-wrap > *:last-child { margin-bottom: 0; page-break-after: avoid; }
  .cps-head { border-bottom: 3px solid #2B3990; padding-bottom: 8px; margin-bottom: 14px; }
  .cps-head .brand { font-size: 12px; font-weight: 900; color: #2B3990; letter-spacing: 0.6px; }
  .cps-head .title { font-size: 19px; font-weight: 700; color: #1a1a1a; margin-top: 2px; }
  .cps-head .docid { float: right; text-align: right; }
  .cps-head .docid .no { font-size: 15px; font-weight: 700; color: #2B3990; font-family: 'IBM Plex Mono', monospace; }
  .cps-head .docid .meta { font-size: 9.5px; color: #666; }
  h2.sec { font-size: 9.5px; font-weight: 700; color: #2B3990; text-transform: uppercase;
           letter-spacing: 0.8px; margin: 9px 0 4px; padding-bottom: 3px; border-bottom: 1px solid #d5d8e8; }
  table.kv { width: 100%; border-collapse: collapse; table-layout: fixed; }
  table.kv td { padding: 2.5px 8px; border-bottom: 1px solid #eee; vertical-align: top; }
  table.kv td.k { color: #666; width: 21%; }
  table.kv td.v { font-weight: 600; width: 29%; }
  table.grid { width: 100%; border-collapse: collapse; font-size: 10.5px; }
  table.grid th { background: #2B3990; color: #fff; padding: 4px 8px; text-align: left; font-weight: 600; }
  table.grid td { padding: 3.5px 8px; border-bottom: 1px solid #e6e6e6; }
  table.grid tr:nth-child(even) td { background: #FAFAFA; }
  .num { text-align: right; font-family: 'IBM Plex Mono', monospace; }
  /* table-layout:fixed keeps the figures row inside A4 — without it the SVG
     cells force the page wider and everything clips at the right edge. */
  table.figs { width: 100%; table-layout: fixed; border-collapse: collapse; margin-top: 8px; }
  .figs td { vertical-align: top; padding-right: 12px; }
  .legend { margin-top: 6px; font-size: 9px; color: #666; }
  .legend span { margin-right: 12px; }
  .swatch { display: inline-block; width: 10px; height: 10px; border: 1px solid #999; vertical-align: middle; margin-right: 3px; }
  /* page-break-inside:avoid keeps the footer from orphaning onto a second sheet */
  .foot { margin-top: 6px; padding-top: 4px; border-top: 1px solid #ddd; font-size: 8.5px; color: #888;
          page-break-inside: avoid; page-break-after: avoid; margin-bottom: 0; }
  .calcnote { margin-top: 5px; padding: 3px 8px; background: #FFF8E1; border-left: 3px solid #FFA000;
              font-size: 8.5px; line-height: 1.35; color: #6b5400; }
  .naflag { padding: 10px 12px; background: #FAFAFA; border-left: 3px solid #ccc; color: #777; font-style: italic; }
</style>

<div class="cps-wrap">

  <div class="cps-head">
    <div class="docid">
      <div class="no">{{ doc.name }}</div>
      <div class="meta">
        {{ doc.status or "" }}{% if doc.docstatus == 1 %} &bull; Submitted{% elif doc.docstatus == 2 %} &bull; Cancelled{% else %} &bull; Draft{% endif %}<br>
        {{ frappe.utils.formatdate(doc.modified, "dd MMM yyyy") }}
      </div>
    </div>
    <div class="brand">VIMIT CONVERTERS LTD</div>
    <div class="title">Customer Product Specification</div>
    <div style="clear:both;"></div>
  </div>

  <table class="kv">
    <tr>
      <td class="k">Specification</td><td class="v">{{ doc.specification_name or "&mdash;" }}</td>
      <td class="k">Customer</td><td class="v">{{ doc.customer or "&mdash;" }}</td>
    </tr>
    <tr>
      <td class="k">Product Type</td><td class="v">{{ doc.product_type or "&mdash;" }}{% if pt %} &bull; {{ pt }}{% endif %}</td>
      <td class="k">Linked Item</td><td class="v">{{ doc.linked_item or "&mdash;" }}</td>
    </tr>
    <tr>
      <td class="k">Job Size</td><td class="v">{{ doc.job_size or "&mdash;" }}</td>
      <td class="k">Printing</td>
      <td class="v">{{ doc.print_type or doc.printing_or_plain or "&mdash;" }}{% if doc.ink_type %} &bull; {{ doc.ink_type }}{% endif %}</td>
    </tr>
  </table>

  {%- if is_carton %}
  <h2 class="sec">Carton Construction</h2>
  <table class="kv">
    <tr>
      <td class="k">Dimensions (L x W x H)</td><td class="v">{{ L }} x {{ W }} x {{ H }} mm</td>
      <td class="k">ID / OD</td><td class="v">{{ doc.idod or "&mdash;" }}</td>
    </tr>
    <tr>
      <td class="k">Ply / Flute</td><td class="v">{{ ply or "&mdash;" }} Ply &bull; {{ doc.flute_type or "&mdash;" }} Flute</td>
      <td class="k">Joint</td><td class="v">{{ joint }} ({{ tab }}mm tab)</td>
    </tr>
  </table>

  <h2 class="sec">Board Build-up</h2>
  <table class="grid">
    <thead><tr><th style="width:22%;">Layer</th><th>Material</th><th class="num" style="width:20%;">GSM</th></tr></thead>
    <tbody>
      {%- set layers = [
            ('1 Ply — Top',    doc.get('1_ply_top_layer_material'), doc.get('1_ply_top_layer_gsm'), true),
            ('2 Ply — Fluting', doc.get('2_ply_top_layer_material'), doc.get('2_ply_fluting_gsm'), true),
            ('3 Ply — Bottom',  doc.get('3_ply_top_layer_material'), doc.get('3_ply_bottom_gsm'), ply in ["3", "5"]),
            ('4 Ply — Fluting', doc.get('4_ply_top_layer_material'), doc.get('4_ply_fluting_gsm'), ply == "5"),
            ('5 Ply',           doc.get('5_ply_top_layer_material'), doc.get('5_ply_fluting_gsm'), ply == "5")
          ] -%}
      {%- for label, mat, g, show in layers %}{% if show %}
      <tr><td>{{ label }}</td><td>{{ mat or "&mdash;" }}</td><td class="num">{{ g or 0 }}</td></tr>
      {%- endif %}{% endfor %}
      <tr><td colspan="2" style="font-weight:700;">Total</td><td class="num" style="font-weight:700;">{{ total_gsm }} gsm</td></tr>
    </tbody>
  </table>

  <h2 class="sec">Board Plan</h2>
  {%- if drawable %}
  {#- Row 1 pairs the figures table with the assembled box, which would otherwise
      leave dead space beside a narrow table. Row 2 gives the flat blank the full
      width — it is the drawing the shop floor actually works from. -#}
  <table class="figs"><tr>
    <td style="width:56%;">
      <table class="grid">
        <thead><tr><th>Board</th><th class="num">Blank / Actual</th><th class="num">Planned (+{{ 2 * TRIM }}mm trim)</th></tr></thead>
        <tbody>
          <tr><td>Width</td><td class="num">{{ aw }} mm</td><td class="num" style="font-weight:700;">{{ pw }} mm</td></tr>
          <tr><td>Length</td><td class="num">{{ al }} mm</td><td class="num" style="font-weight:700;">{{ pl }} mm</td></tr>
          <tr><td>Carton flap</td><td class="num">{{ flap }} mm</td><td class="num">&mdash;</td></tr>
          <tr><td>Approximate weight</td><td class="num">{{ total_gsm }} gsm</td>
              <td class="num" style="font-weight:700;">{{ "%.1f"|format(weight) }} g</td></tr>
        </tbody>
      </table>
    </td>
    <td style="padding-right:0;">{{ assembled(L, W, H, (is_tray or one_flap),
            "Assembled tray" if is_tray else ("Assembled — top open" if one_flap else "Assembled — closed")) }}</td>
  </tr></table>

  <div style="margin-top:6px;">
    {% if is_tray %}{{ flat_tray(L, W, H) }}{% else %}{{ flat_rsc(L, W, H, flap, tab, one_flap, is_stitch) }}{% endif %}
  </div>

  <div class="legend" style="margin-top:4px;">
    <span><span style="display:inline-block;width:16px;border-top:2px dashed #FF6B35;vertical-align:middle;margin-right:3px;"></span>Fold line</span>
    {%- if is_tray %}
    <span><span class="swatch" style="background:#E7E0F4;"></span>Base</span>
    <span><span class="swatch" style="background:#D7EDD8;"></span>Walls</span>
    {%- else %}
    <span><span class="swatch" style="background:#E2E4F4;"></span>Front/Back</span>
    <span><span class="swatch" style="background:#DBDEF1;"></span>Side</span>
    <span><span class="swatch" style="background:#DDE1F2;"></span>Flaps</span>
    <span><span class="swatch" style="background:{{ '#F7D8D8' if is_stitch else '#D2EBD3' }};"></span>{{ 'Stitch flap' if is_stitch else 'Glue tab' }}</span>
    {%- endif %}
  </div>

  {#- Two short lines rather than one long one: wkhtmltopdf clips the tail of a
      long single-line run at the right edge instead of wrapping it cleanly. -#}
  <div style="margin-top:6px;font-size:8.5px;color:#777;line-height:1.5;">
    Blank Width = {% if is_tray %}W + 2H{% elif one_flap %}H + Flap{% else %}Flap + H + Flap{% endif %}
    &nbsp;&bull;&nbsp;
    Blank Length = {% if is_tray %}L + 2H{% else %}(2 x L) + (2 x W) + {{ tab }}mm tab{% endif %}
    &nbsp;&bull;&nbsp; Planned = Blank + 2 x {{ TRIM }}mm trim per outer edge<br>
    Approximate weight = (Planned Width x Planned Length / 1,000,000) x Total GSM
  </div>

  {%- if stale %}
  <div class="calcnote" style="background:#FDECEA;border-left-color:#C62828;color:#7f1d1d;">
    <b>Stored board plan was out of date</b> &mdash; it disagreed with the carton dimensions on this
    specification, so the figures above were recomputed at print time. Revise the spec to refresh
    the stored values.</div>
  {%- endif %}
  {%- if CALCULATED %}
  <div class="calcnote"><b>Calculated sheet</b> &mdash; board plan computed at print time from the carton
    dimensions, <b>not stored</b> on this specification. Revise the spec to store it.</div>
  {%- endif %}

  {%- elif pt == "Die Cut" %}
  <div class="naflag">Die Cut &mdash; blank layout not available. The custom die shape governs the board plan.</div>
  {%- elif ply == "SFK" %}
  <div class="naflag">Board plan is not applicable for SFK ply &mdash; the web is run un-glued.</div>
  {%- else %}
  <div class="naflag">Board plan unavailable &mdash; carton dimensions and product type are incomplete on this specification.</div>
  {%- endif %}
  {%- endif %}

  {%- if doc.internal_notes or doc.special_instructions_carton %}
  <h2 class="sec">Notes</h2>
  <div style="font-size:10px;white-space:pre-wrap;">{{ doc.special_instructions_carton or "" }}{% if doc.special_instructions_carton and doc.internal_notes %}

{% endif %}{{ doc.internal_notes or "" }}</div>
  {%- endif %}

  <div class="foot">
    {{ doc.name }} &bull; {{ doc.specification_name or "" }} &bull; printed {{ frappe.utils.formatdate(frappe.utils.nowdate(), "dd MMM yyyy") }}
    {%- if CALCULATED %} &bull; board plan calculated at print time{% endif %}
  </div>

</div>

{#-
  ══════════════════════════════════════════════════════════════════════
  Customer Product Specification — spec sheet
  SINGLE SOURCE for BOTH print formats. push_cps_board_plan.py generates:

    "Customer Product Spec"               CALCULATED = false
    "Customer Product Spec (Calculated)"  CALCULATED = true

  by rewriting the CALCULATED line below. Never edit the two generated
  formats in the Frappe UI — edit this file and re-push, or the layouts
  drift apart.

  CALCULATED = false → Board Plan reads the stored board_* fields, falling
                       back to the computed value where a field is empty.
  CALCULATED = true  → Board Plan is recomputed from the carton dimensions
                       and the stored board_* fields are ignored entirely.
                       This is the variant for the back-catalogue of specs
                       submitted before the Board Plan fields existed.

  wkhtmltopdf: no named @page rules (silently ignored), and the last page
  container must suppress page-break-after or a blank sheet is emitted.
  ══════════════════════════════════════════════════════════════════════
-#}
{%- set CALCULATED = true -%}

{#- ── Inputs ──────────────────────────────────────────────────────── -#}
{%- set pt        = doc.product_type_carton or "" -%}
{%- set ply       = doc.ply or "" -%}
{%- set L         = doc.ctn_length_mm or 0 -%}
{%- set W         = doc.ctn_width_mm or 0 -%}
{%- set H         = doc.ctn_height_mm or 0 -%}
{%- set joint     = doc.joint_type or "Stitched" -%}
{%- set is_stitch = (joint == "Stitched") -%}
{#- VCL standard: 30mm tab for every joint type (stitch flap reduced from 40mm 2026-07-23). -#}
{%- set tab       = 30 -%}
{%- set TRIM      = 10 -%}

{%- set is_carton = (doc.product_type == "Carton") -%}
{%- set is_tray   = (pt == "Tray") -%}
{%- set one_flap  = (pt == "1 Flap RSC") -%}
{%- set drawable  = is_carton and ply != "SFK" and pt not in ["", "Die Cut"] and L > 0 and W > 0
                    and (is_tray or (H > 0)) -%}

{#- ── Flap ─────────────────────────────────────────────────────────── -#}
{%- set flap_calc = 0 if ply == "SFK" else (((W + 5) / 2) | round(0, 'ceil') | int) -%}
{%- if CALCULATED -%}
  {%- set flap = flap_calc -%}
{%- else -%}
  {%- set flap = doc.ctn_flap_mm or flap_calc -%}
{%- endif -%}

{#- ── Blank sizes ──────────────────────────────────────────────────── -#}
{%- if is_tray -%}
  {%- set bw = W + 2 * H -%}
  {%- set bl = L + 2 * H -%}
{%- elif one_flap -%}
  {%- set bw = H + flap -%}
  {%- set bl = (2 * L) + (2 * W) + tab -%}
{%- else -%}
  {%- set bw = flap + H + flap -%}
  {%- set bl = (2 * L) + (2 * W) + tab -%}
{%- endif -%}

{%- set pw_calc = bw + (2 * TRIM) -%}
{%- set pl_calc = bl + (2 * TRIM) -%}

{#- ── GSM build-up ─────────────────────────────────────────────────── -#}
{%- set gsm_12 = (doc.get('1_ply_top_layer_gsm') or 0) + (doc.get('2_ply_fluting_gsm') or 0) -%}
{%- set gsm_3  = (doc.get('3_ply_bottom_gsm') or 0) if ply in ["3", "5"] else 0 -%}
{%- set gsm_45 = ((doc.get('4_ply_fluting_gsm') or 0) + (doc.get('5_ply_fluting_gsm') or 0)) if ply == "5" else 0 -%}
{%- set total_gsm = gsm_12 + gsm_3 + gsm_45 -%}

{#- ── Resolve the figures actually printed ─────────────────────────── -#}
{%- set stale = false -%}
{%- if CALCULATED -%}
  {%- set pw = pw_calc -%}
  {%- set pl = pl_calc -%}
  {%- set aw = bw -%}
  {%- set al = bl -%}
  {%- set weight = ((pw_calc * pl_calc) / 1000000.0) * total_gsm -%}
{%- else -%}
  {#- The geometry fully determines the blank, so stored values that disagree with
      it are stale, not a legitimate override. Printing them produced a Planned
      smaller than its own Blank on CTN-SPEC-00022. Fall back to the computed
      figures and say so, rather than print an impossible table. -#}
  {%- set s_aw = doc.board_width_actual_mm or 0 -%}
  {%- set s_al = doc.board_length_actual_mm or 0 -%}
  {%- set s_pw = doc.board_width_planned_mm or 0 -%}
  {%- set s_pl = doc.board_length_planned_mm or 0 -%}
  {%- if (s_aw and s_aw != bw) or (s_al and s_al != bl)
       or (s_pw and s_pw != pw_calc) or (s_pl and s_pl != pl_calc) -%}
    {%- set stale = true -%}
    {%- set pw = pw_calc -%}
    {%- set pl = pl_calc -%}
    {%- set aw = bw -%}
    {%- set al = bl -%}
    {%- set weight = ((pw_calc * pl_calc) / 1000000.0) * total_gsm -%}
  {%- else -%}
    {%- set pw = s_pw or pw_calc -%}
    {%- set pl = s_pl or pl_calc -%}
    {%- set aw = s_aw or bw -%}
    {%- set al = s_al or bl -%}
    {%- set weight = doc.approximate_weight_grams or (((pw_calc * pl_calc) / 1000000.0) * total_gsm) -%}
  {%- endif -%}
{%- endif -%}

{#- ══ Flat blank — RSC ═════════════════════════════════════════════ -#}
{%- macro flat_rsc(L, W, H, flap, tab, one_flap, is_stitch) -%}
  {%- set totalW = tab + (2 * L) + (2 * W) -%}
  {%- set totalH = (H + flap) if one_flap else (flap + H + flap) -%}
  {#- Widths are tuned to A4 at 12mm margins (~700 CSS px of content box). -#}
  {%- set scale  = [0.40, 510.0 / totalW, 175.0 / totalH] | min -%}
  {%- set ox = 34 -%}{%- set oy = 30 -%}
  {%- set body_y = 0 if one_flap else flap -%}
  {%- set svgW = (totalW * scale) + 76 -%}
  {%- set svgH = (totalH * scale) + 74 -%}{#- room for the dimension row + blank caption -#}
  {%- set tab_fill = '#F7D8D8' if is_stitch else '#D2EBD3' -%}
  {%- set tab_label = 'Stitch Flap' if is_stitch else 'Glue Tab' -%}
<svg width="{{ svgW|round(1) }}" height="{{ svgH|round(1) }}" viewBox="0 0 {{ svgW|round(1) }} {{ svgH|round(1) }}"
     style="background:#FAFAFA;border:1px solid #ddd;border-radius:4px;">
  {#- Panel width L is a Front/Back face; panel width W is a Side face. -#}
  {%- set body = [
        (0, tab, tab_fill, tab_label),
        (tab, L, '#E2E4F4', 'Front (' ~ L ~ ')'),
        (tab + L, W, '#DBDEF1', 'Side (' ~ W ~ ')'),
        (tab + L + W, L, '#E2E4F4', 'Back (' ~ L ~ ')'),
        (tab + L + W + L, W, '#DBDEF1', 'Side (' ~ W ~ ')')
      ] -%}
  {%- for x, w, fill, label in body %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ (oy + body_y * scale)|round(2) }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (H * scale)|round(2) }}"
        fill="{{ fill }}" stroke="#333333" stroke-width="1.5"/>
  {%- if (w * scale) > 34 %}
  <text x="{{ (ox + (x + w / 2.0) * scale)|round(2) }}" y="{{ (oy + (body_y + H / 2.0) * scale)|round(2) }}"
        text-anchor="middle" dominant-baseline="middle" font-size="9" fill="#333" font-weight="500">{{ label }}</text>
  {%- endif %}
  {%- endfor %}
  {%- set flaps = [(tab, L), (tab + L, W), (tab + L + W, L), (tab + L + W + L, W)] -%}
  {%- for x, w in flaps %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ (oy + (body_y + H) * scale)|round(2) }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (flap * scale)|round(2) }}"
        fill="#DDE1F2" stroke="#333333" stroke-width="1.5"/>
  {%- if not one_flap %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ oy }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (flap * scale)|round(2) }}"
        fill="#DDE1F2" stroke="#333333" stroke-width="1.5"/>
  {%- endif %}
  <line x1="{{ (ox + x * scale)|round(2) }}" y1="{{ oy }}"
        x2="{{ (ox + x * scale)|round(2) }}" y2="{{ (oy + totalH * scale)|round(2) }}"
        stroke="#FF6B35" stroke-width="1.4" stroke-dasharray="6,4"/>
  {%- endfor %}
  <line x1="{{ (ox + tab * scale)|round(2) }}" y1="{{ (oy + (body_y + H) * scale)|round(2) }}"
        x2="{{ (ox + totalW * scale)|round(2) }}" y2="{{ (oy + (body_y + H) * scale)|round(2) }}"
        stroke="#FF6B35" stroke-width="1" stroke-dasharray="4,3"/>
  {%- if not one_flap %}
  <line x1="{{ (ox + tab * scale)|round(2) }}" y1="{{ (oy + flap * scale)|round(2) }}"
        x2="{{ (ox + totalW * scale)|round(2) }}" y2="{{ (oy + flap * scale)|round(2) }}"
        stroke="#FF6B35" stroke-width="1" stroke-dasharray="4,3"/>
  {%- else %}
  <text x="{{ (ox + (totalW / 2.0) * scale)|round(2) }}" y="{{ oy - 10 }}"
        text-anchor="middle" font-size="8" fill="#999" font-style="italic">Open end (no flap)</text>
  {%- endif %}
  <text x="{{ (ox + (tab + L / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 13)|round(2) }}"
        text-anchor="middle" font-size="9" fill="#666">{{ L }}mm</text>
  <text x="{{ (ox + (tab + L + W / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 13)|round(2) }}"
        text-anchor="middle" font-size="9" fill="#666">{{ W }}mm</text>
  <text x="{{ (ox + totalW * scale + 5)|round(2) }}" y="{{ (oy + (body_y + H / 2.0) * scale)|round(2) }}"
        text-anchor="start" dominant-baseline="middle" font-size="9" fill="#666">{{ H }}mm</text>
  <text x="{{ (ox + totalW * scale + 5)|round(2) }}" y="{{ (oy + (body_y + H + flap / 2.0) * scale)|round(2) }}"
        text-anchor="start" dominant-baseline="middle" font-size="9" fill="#666">{{ flap }}mm</text>
  <text x="{{ (ox + (totalW / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 32)|round(2) }}"
        text-anchor="middle" font-size="10" fill="#2B3990" font-weight="600">Blank: {{ totalH }} (W) x {{ totalW }} (L) mm</text>
</svg>
{%- endmacro -%}

{#- ══ Flat blank — Tray ════════════════════════════════════════════ -#}
{%- macro flat_tray(L, W, H) -%}
  {%- set totalW = H + W + H -%}
  {%- set totalH = H + L + H -%}
  {%- set scale  = [0.52, 380.0 / totalW, 250.0 / totalH] | min -%}
  {%- set ox = 30 -%}{%- set oy = 30 -%}
  {%- set svgW = (totalW * scale) + 60 -%}
  {%- set svgH = (totalH * scale) + 74 -%}
<svg width="{{ svgW|round(1) }}" height="{{ svgH|round(1) }}" viewBox="0 0 {{ svgW|round(1) }} {{ svgH|round(1) }}"
     style="background:#FAFAFA;border:1px solid #ddd;border-radius:4px;">
  {%- set panels = [
        (H, H, W, L, '#E7E0F4', 'Base (' ~ L ~ ' x ' ~ W ~ ')'),
        (H, 0, W, H, '#D7EDD8', 'Front'),
        (H, H + L, W, H, '#D7EDD8', 'Back'),
        (0, H, H, L, '#E5F3E5', 'Side'),
        (H + W, H, H, L, '#E5F3E5', 'Side')
      ] -%}
  {%- for x, y, w, h, fill, label in panels %}
  <rect x="{{ (ox + x * scale)|round(2) }}" y="{{ (oy + y * scale)|round(2) }}"
        width="{{ (w * scale)|round(2) }}" height="{{ (h * scale)|round(2) }}"
        fill="{{ fill }}" stroke="#333333" stroke-width="1.5"/>
  {%- if (w * scale) > 44 and (h * scale) > 16 %}
  <text x="{{ (ox + (x + w / 2.0) * scale)|round(2) }}" y="{{ (oy + (y + h / 2.0) * scale)|round(2) }}"
        text-anchor="middle" dominant-baseline="middle" font-size="9" fill="#333" font-weight="500">{{ label }}</text>
  {%- endif %}
  {%- endfor %}
  {%- for fx in [H, H + W] %}
  <line x1="{{ (ox + fx * scale)|round(2) }}" y1="{{ oy }}" x2="{{ (ox + fx * scale)|round(2) }}"
        y2="{{ (oy + totalH * scale)|round(2) }}" stroke="#FF6B35" stroke-width="1.4" stroke-dasharray="6,4"/>
  {%- endfor %}
  {%- for fy in [H, H + L] %}
  <line x1="{{ ox }}" y1="{{ (oy + fy * scale)|round(2) }}" x2="{{ (ox + totalW * scale)|round(2) }}"
        y2="{{ (oy + fy * scale)|round(2) }}" stroke="#FF6B35" stroke-width="1.4" stroke-dasharray="6,4"/>
  {%- endfor %}
  <text x="{{ (ox + (totalW / 2.0) * scale)|round(2) }}" y="{{ (oy + totalH * scale + 30)|round(2) }}"
        text-anchor="middle" font-size="10" fill="#2B3990" font-weight="600">Blank: {{ totalW }} x {{ totalH }} mm</text>
</svg>
{%- endmacro -%}

{#- ══ Assembled box ════════════════════════════════════════════════ -#}
{%- macro assembled(L, W, H, open_top, caption) -%}
  {%- set DX = 0.50 -%}{%- set DY = 0.30 -%}
  {%- set scale = [0.34, 150.0 / (L + W * DX), 130.0 / (H + W * DY)] | min -%}
  {%- set l = L * scale -%}{%- set h = H * scale -%}
  {%- set dx = W * scale * DX -%}{%- set dy = W * scale * DY -%}
  {#- Left margin clears the "H 000mm" callout (anchored end), right margin the "W 000mm" -#}
  {%- set ox = 52 -%}{%- set oy = 28 + dy -%}
  {%- set svgW = l + dx + 110 -%}
  {%- set svgH = h + dy + 62 -%}
<svg width="{{ svgW|round(1) }}" height="{{ svgH|round(1) }}" viewBox="0 0 {{ svgW|round(1) }} {{ svgH|round(1) }}"
     style="background:#FAFAFA;border:1px solid #ddd;border-radius:4px;">
  {%- if open_top %}
  <polygon points="{{ (ox + 3)|round(2) }},{{ (oy + 2)|round(2) }}
                   {{ (ox + l - 3)|round(2) }},{{ (oy + 2)|round(2) }}
                   {{ (ox + l - 3 + dx)|round(2) }},{{ (oy + 2 - dy)|round(2) }}
                   {{ (ox + 3 + dx)|round(2) }},{{ (oy + 2 - dy)|round(2) }}"
           fill="#C1C5E1" stroke="#333333" stroke-width="0.8"/>
  {%- else %}
  <polygon points="{{ ox }},{{ oy|round(2) }} {{ (ox + l)|round(2) }},{{ oy|round(2) }}
                   {{ (ox + l + dx)|round(2) }},{{ (oy - dy)|round(2) }} {{ (ox + dx)|round(2) }},{{ (oy - dy)|round(2) }}"
           fill="#BCC2E5" stroke="#333333" stroke-width="1.6"/>
  {%- endif %}
  <polygon points="{{ (ox + l)|round(2) }},{{ oy|round(2) }}
                   {{ (ox + l + dx)|round(2) }},{{ (oy - dy)|round(2) }}
                   {{ (ox + l + dx)|round(2) }},{{ (oy - dy + h)|round(2) }}
                   {{ (ox + l)|round(2) }},{{ (oy + h)|round(2) }}"
           fill="#C9CEEA" stroke="#333333" stroke-width="1.6"/>
  <rect x="{{ ox }}" y="{{ oy|round(2) }}" width="{{ l|round(2) }}" height="{{ h|round(2) }}"
        fill="#D1D5ED" stroke="#333333" stroke-width="1.8"/>
  {%- if open_top %}
  <line x1="{{ ox }}" y1="{{ oy|round(2) }}" x2="{{ (ox + dx)|round(2) }}" y2="{{ (oy - dy)|round(2) }}"
        stroke="#333333" stroke-width="1.6"/>
  <line x1="{{ (ox + dx)|round(2) }}" y1="{{ (oy - dy)|round(2) }}"
        x2="{{ (ox + l + dx)|round(2) }}" y2="{{ (oy - dy)|round(2) }}" stroke="#333333" stroke-width="1.6"/>
  <text x="{{ (ox + l / 2.0 + dx / 2.0)|round(2) }}" y="{{ (oy - dy - 7)|round(2) }}"
        text-anchor="middle" font-size="8" fill="#999" font-style="italic">Open top</text>
  {%- endif %}
  <text x="{{ (ox + l / 2.0)|round(2) }}" y="{{ (oy + h / 2.0)|round(2) }}"
        text-anchor="middle" dominant-baseline="middle" font-size="9" fill="#333" font-weight="500">{{ L }} x {{ H }}</text>
  <text x="{{ (ox + l / 2.0)|round(2) }}" y="{{ (oy + h + 15)|round(2) }}"
        text-anchor="middle" font-size="9" fill="#666">L {{ L }}mm</text>
  <text x="{{ (ox - 7)|round(2) }}" y="{{ (oy + h / 2.0)|round(2) }}"
        text-anchor="end" dominant-baseline="middle" font-size="9" fill="#666">H {{ H }}mm</text>
  {#- W is the receding depth. Dimension it on the top-LEFT receding edge: that
      edge is on the silhouette, so the callout sits outside the solid. Placed at
      the right it landed beside the right face's vertical edge and read as the
      height. Angle is constant — atan(DY/DX) = 31 degrees — so it can be hardcoded. -#}
  {%- set nlen = ((dx * dx) + (dy * dy)) ** 0.5 -%}
  {%- set nx = -dy / nlen -%}{%- set ny = -dx / nlen -%}
  {%- set k = 11 -%}
  <line x1="{{ (ox + k * nx)|round(2) }}" y1="{{ (oy + k * ny)|round(2) }}"
        x2="{{ (ox + dx + k * nx)|round(2) }}" y2="{{ (oy - dy + k * ny)|round(2) }}"
        stroke="#999" stroke-width="0.6"/>
  <line x1="{{ ox }}" y1="{{ oy|round(2) }}" x2="{{ (ox + k * nx)|round(2) }}"
        y2="{{ (oy + k * ny)|round(2) }}" stroke="#999" stroke-width="0.5"/>
  <line x1="{{ (ox + dx)|round(2) }}" y1="{{ (oy - dy)|round(2) }}"
        x2="{{ (ox + dx + k * nx)|round(2) }}" y2="{{ (oy - dy + k * ny)|round(2) }}"
        stroke="#999" stroke-width="0.5"/>
  {%- set wlx = ox + (dx / 2.0) + (k + 8) * nx -%}
  {%- set wly = oy - (dy / 2.0) + (k + 8) * ny -%}
  <text x="{{ wlx|round(2) }}" y="{{ wly|round(2) }}" text-anchor="middle" dominant-baseline="middle"
        font-size="9" fill="#666"
        transform="rotate(-31, {{ wlx|round(2) }}, {{ wly|round(2) }})">W {{ W }}mm</text>
  <text x="{{ (ox + (l + dx) / 2.0)|round(2) }}" y="{{ (svgH - 9)|round(2) }}"
        text-anchor="middle" font-size="10" fill="#2B3990" font-weight="600">{{ caption }}</text>
</svg>
{%- endmacro -%}

<style>
  @page { size: A4; margin: 10mm 12mm; }
  .cps-wrap { font-family: 'Inter', Calibri, Arial, sans-serif; color: #1a1a1a; font-size: 10.5px; line-height: 1.3; }
  /* wkhtmltopdf emits a trailing blank sheet unless the container suppresses
     page-break-after AND its last child has no bottom margin. :last-child alone
     is not enough — printview may wrap the format in further elements. */
  .cps-wrap { page-break-after: avoid; margin-bottom: 0; padding-bottom: 0; }
  .cps-wrap > *:last-child { margin-bottom: 0; page-break-after: avoid; }
  .cps-head { border-bottom: 3px solid #2B3990; padding-bottom: 8px; margin-bottom: 14px; }
  .cps-head .brand { font-size: 12px; font-weight: 900; color: #2B3990; letter-spacing: 0.6px; }
  .cps-head .title { font-size: 19px; font-weight: 700; color: #1a1a1a; margin-top: 2px; }
  .cps-head .docid { float: right; text-align: right; }
  .cps-head .docid .no { font-size: 15px; font-weight: 700; color: #2B3990; font-family: 'IBM Plex Mono', monospace; }
  .cps-head .docid .meta { font-size: 9.5px; color: #666; }
  h2.sec { font-size: 9.5px; font-weight: 700; color: #2B3990; text-transform: uppercase;
           letter-spacing: 0.8px; margin: 9px 0 4px; padding-bottom: 3px; border-bottom: 1px solid #d5d8e8; }
  table.kv { width: 100%; border-collapse: collapse; table-layout: fixed; }
  table.kv td { padding: 2.5px 8px; border-bottom: 1px solid #eee; vertical-align: top; }
  table.kv td.k { color: #666; width: 21%; }
  table.kv td.v { font-weight: 600; width: 29%; }
  table.grid { width: 100%; border-collapse: collapse; font-size: 10.5px; }
  table.grid th { background: #2B3990; color: #fff; padding: 4px 8px; text-align: left; font-weight: 600; }
  table.grid td { padding: 3.5px 8px; border-bottom: 1px solid #e6e6e6; }
  table.grid tr:nth-child(even) td { background: #FAFAFA; }
  .num { text-align: right; font-family: 'IBM Plex Mono', monospace; }
  /* table-layout:fixed keeps the figures row inside A4 — without it the SVG
     cells force the page wider and everything clips at the right edge. */
  table.figs { width: 100%; table-layout: fixed; border-collapse: collapse; margin-top: 8px; }
  .figs td { vertical-align: top; padding-right: 12px; }
  .legend { margin-top: 6px; font-size: 9px; color: #666; }
  .legend span { margin-right: 12px; }
  .swatch { display: inline-block; width: 10px; height: 10px; border: 1px solid #999; vertical-align: middle; margin-right: 3px; }
  /* page-break-inside:avoid keeps the footer from orphaning onto a second sheet */
  .foot { margin-top: 6px; padding-top: 4px; border-top: 1px solid #ddd; font-size: 8.5px; color: #888;
          page-break-inside: avoid; page-break-after: avoid; margin-bottom: 0; }
  .calcnote { margin-top: 5px; padding: 3px 8px; background: #FFF8E1; border-left: 3px solid #FFA000;
              font-size: 8.5px; line-height: 1.35; color: #6b5400; }
  .naflag { padding: 10px 12px; background: #FAFAFA; border-left: 3px solid #ccc; color: #777; font-style: italic; }
</style>

<div class="cps-wrap">

  <div class="cps-head">
    <div class="docid">
      <div class="no">{{ doc.name }}</div>
      <div class="meta">
        {{ doc.status or "" }}{% if doc.docstatus == 1 %} &bull; Submitted{% elif doc.docstatus == 2 %} &bull; Cancelled{% else %} &bull; Draft{% endif %}<br>
        {{ frappe.utils.formatdate(doc.modified, "dd MMM yyyy") }}
      </div>
    </div>
    <div class="brand">VIMIT CONVERTERS LTD</div>
    <div class="title">Customer Product Specification</div>
    <div style="clear:both;"></div>
  </div>

  <table class="kv">
    <tr>
      <td class="k">Specification</td><td class="v">{{ doc.specification_name or "&mdash;" }}</td>
      <td class="k">Customer</td><td class="v">{{ doc.customer or "&mdash;" }}</td>
    </tr>
    <tr>
      <td class="k">Product Type</td><td class="v">{{ doc.product_type or "&mdash;" }}{% if pt %} &bull; {{ pt }}{% endif %}</td>
      <td class="k">Linked Item</td><td class="v">{{ doc.linked_item or "&mdash;" }}</td>
    </tr>
    <tr>
      <td class="k">Job Size</td><td class="v">{{ doc.job_size or "&mdash;" }}</td>
      <td class="k">Printing</td>
      <td class="v">{{ doc.print_type or doc.printing_or_plain or "&mdash;" }}{% if doc.ink_type %} &bull; {{ doc.ink_type }}{% endif %}</td>
    </tr>
  </table>

  {%- if is_carton %}
  <h2 class="sec">Carton Construction</h2>
  <table class="kv">
    <tr>
      <td class="k">Dimensions (L x W x H)</td><td class="v">{{ L }} x {{ W }} x {{ H }} mm</td>
      <td class="k">ID / OD</td><td class="v">{{ doc.idod or "&mdash;" }}</td>
    </tr>
    <tr>
      <td class="k">Ply / Flute</td><td class="v">{{ ply or "&mdash;" }} Ply &bull; {{ doc.flute_type or "&mdash;" }} Flute</td>
      <td class="k">Joint</td><td class="v">{{ joint }} ({{ tab }}mm tab)</td>
    </tr>
  </table>

  <h2 class="sec">Board Build-up</h2>
  <table class="grid">
    <thead><tr><th style="width:22%;">Layer</th><th>Material</th><th class="num" style="width:20%;">GSM</th></tr></thead>
    <tbody>
      {%- set layers = [
            ('1 Ply — Top',    doc.get('1_ply_top_layer_material'), doc.get('1_ply_top_layer_gsm'), true),
            ('2 Ply — Fluting', doc.get('2_ply_top_layer_material'), doc.get('2_ply_fluting_gsm'), true),
            ('3 Ply — Bottom',  doc.get('3_ply_top_layer_material'), doc.get('3_ply_bottom_gsm'), ply in ["3", "5"]),
            ('4 Ply — Fluting', doc.get('4_ply_top_layer_material'), doc.get('4_ply_fluting_gsm'), ply == "5"),
            ('5 Ply',           doc.get('5_ply_top_layer_material'), doc.get('5_ply_fluting_gsm'), ply == "5")
          ] -%}
      {%- for label, mat, g, show in layers %}{% if show %}
      <tr><td>{{ label }}</td><td>{{ mat or "&mdash;" }}</td><td class="num">{{ g or 0 }}</td></tr>
      {%- endif %}{% endfor %}
      <tr><td colspan="2" style="font-weight:700;">Total</td><td class="num" style="font-weight:700;">{{ total_gsm }} gsm</td></tr>
    </tbody>
  </table>

  <h2 class="sec">Board Plan</h2>
  {%- if drawable %}
  {#- Row 1 pairs the figures table with the assembled box, which would otherwise
      leave dead space beside a narrow table. Row 2 gives the flat blank the full
      width — it is the drawing the shop floor actually works from. -#}
  <table class="figs"><tr>
    <td style="width:56%;">
      <table class="grid">
        <thead><tr><th>Board</th><th class="num">Blank / Actual</th><th class="num">Planned (+{{ 2 * TRIM }}mm trim)</th></tr></thead>
        <tbody>
          <tr><td>Width</td><td class="num">{{ aw }} mm</td><td class="num" style="font-weight:700;">{{ pw }} mm</td></tr>
          <tr><td>Length</td><td class="num">{{ al }} mm</td><td class="num" style="font-weight:700;">{{ pl }} mm</td></tr>
          <tr><td>Carton flap</td><td class="num">{{ flap }} mm</td><td class="num">&mdash;</td></tr>
          <tr><td>Approximate weight</td><td class="num">{{ total_gsm }} gsm</td>
              <td class="num" style="font-weight:700;">{{ "%.1f"|format(weight) }} g</td></tr>
        </tbody>
      </table>
    </td>
    <td style="padding-right:0;">{{ assembled(L, W, H, (is_tray or one_flap),
            "Assembled tray" if is_tray else ("Assembled — top open" if one_flap else "Assembled — closed")) }}</td>
  </tr></table>

  <div style="margin-top:6px;">
    {% if is_tray %}{{ flat_tray(L, W, H) }}{% else %}{{ flat_rsc(L, W, H, flap, tab, one_flap, is_stitch) }}{% endif %}
  </div>

  <div class="legend" style="margin-top:4px;">
    <span><span style="display:inline-block;width:16px;border-top:2px dashed #FF6B35;vertical-align:middle;margin-right:3px;"></span>Fold line</span>
    {%- if is_tray %}
    <span><span class="swatch" style="background:#E7E0F4;"></span>Base</span>
    <span><span class="swatch" style="background:#D7EDD8;"></span>Walls</span>
    {%- else %}
    <span><span class="swatch" style="background:#E2E4F4;"></span>Front/Back</span>
    <span><span class="swatch" style="background:#DBDEF1;"></span>Side</span>
    <span><span class="swatch" style="background:#DDE1F2;"></span>Flaps</span>
    <span><span class="swatch" style="background:{{ '#F7D8D8' if is_stitch else '#D2EBD3' }};"></span>{{ 'Stitch flap' if is_stitch else 'Glue tab' }}</span>
    {%- endif %}
  </div>

  {#- Two short lines rather than one long one: wkhtmltopdf clips the tail of a
      long single-line run at the right edge instead of wrapping it cleanly. -#}
  <div style="margin-top:6px;font-size:8.5px;color:#777;line-height:1.5;">
    Blank Width = {% if is_tray %}W + 2H{% elif one_flap %}H + Flap{% else %}Flap + H + Flap{% endif %}
    &nbsp;&bull;&nbsp;
    Blank Length = {% if is_tray %}L + 2H{% else %}(2 x L) + (2 x W) + {{ tab }}mm tab{% endif %}
    &nbsp;&bull;&nbsp; Planned = Blank + 2 x {{ TRIM }}mm trim per outer edge<br>
    Approximate weight = (Planned Width x Planned Length / 1,000,000) x Total GSM
  </div>

  {%- if stale %}
  <div class="calcnote" style="background:#FDECEA;border-left-color:#C62828;color:#7f1d1d;">
    <b>Stored board plan was out of date</b> &mdash; it disagreed with the carton dimensions on this
    specification, so the figures above were recomputed at print time. Revise the spec to refresh
    the stored values.</div>
  {%- endif %}
  {%- if CALCULATED %}
  <div class="calcnote"><b>Calculated sheet</b> &mdash; board plan computed at print time from the carton
    dimensions, <b>not stored</b> on this specification. Revise the spec to store it.</div>
  {%- endif %}

  {%- elif pt == "Die Cut" %}
  <div class="naflag">Die Cut &mdash; blank layout not available. The custom die shape governs the board plan.</div>
  {%- elif ply == "SFK" %}
  <div class="naflag">Board plan is not applicable for SFK ply &mdash; the web is run un-glued.</div>
  {%- else %}
  <div class="naflag">Board plan unavailable &mdash; carton dimensions and product type are incomplete on this specification.</div>
  {%- endif %}
  {%- endif %}

  {%- if doc.internal_notes or doc.special_instructions_carton %}
  <h2 class="sec">Notes</h2>
  <div style="font-size:10px;white-space:pre-wrap;">{{ doc.special_instructions_carton or "" }}{% if doc.special_instructions_carton and doc.internal_notes %}

{% endif %}{{ doc.internal_notes or "" }}</div>
  {%- endif %}

  <div class="foot">
    {{ doc.name }} &bull; {{ doc.specification_name or "" }} &bull; printed {{ frappe.utils.formatdate(frappe.utils.nowdate(), "dd MMM yyyy") }}
    {%- if CALCULATED %} &bull; board plan calculated at print time{% endif %}
  </div>

</div>
